import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(p,'utf8'),json=p=>JSON.parse(read(p));
const dir='content/uc3m/tema-18/';
const manual=read(dir+'manual.md'),sources=read(dir+'fuentes.md');
const bank=json(dir+'preguntas.json'),matrix=json(dir+'matriz.json');
const cotejo=read(dir+'cotejo-integral-2026-11-04.md');
const acta=read('content/uc3m/CIERRE_DOCUMENTAL_T18_20261106.md');
const guide=read('content/uc3m/GUIA_EXAMEN_2026.md');
const status=read('AUDITORIA_CONTINUA.md');
const additional=json('data/uc3m-repasos-complementarios-20261106.json').paquetes.find(p=>p.id==='UC3M-ADIC-20261106-LOTE');
const economy=json('data/uc3m-repaso-presupuesto-contratacion-t18-t20-20261106.json');
assert.equal(matrix.estado,'EN_REVISION_USUARIO');
assert.equal(matrix.cobertura.length,8);
assert.equal(bank.preguntas.length,12);
const headings=[...manual.matchAll(/^## (\d+)\. /gm)].map(m=>Number(m[1])).filter(n=>n<=18);
assert.deepEqual([...new Set(headings)],Array.from({length:18},(_,i)=>i+1),'Falta epigrafe base');
assert.ok(manual.includes('CIERRE_DOCUMENTAL_T18_20261106.md'));
assert.ok(sources.includes('CIERRE_DOCUMENTAL_T18_20261106.md'));
assert.ok(sources.includes('BOCM-20251230-28.PDF'));
assert.ok(sources.includes('BOE-A-2026-3217'));
assert.ok(manual.includes('**300.468.067,59')||manual.includes('300.468.067,59'));
assert.ok(manual.includes('**146.834.705,33')||manual.includes('146.834.705,33'));
assert.ok(manual.includes('**120 días**')||manual.includes('120 días'));
assert.ok(acta.includes('30/60/90/120')&&acta.includes('art. 56.3'));
const ids=new Set();
for(const q of bank.preguntas){
 assert.ok(q.id&&!ids.has(q.id),'Identificador duplicado '+q.id);ids.add(q.id);
 assert.equal(q.opciones.length,4);assert.equal(new Set(q.opciones).size,4);
 assert.ok(q.opciones.every(x=>typeof x==='string'&&x.trim()));
 assert.ok(Number.isInteger(q.correcta)&&q.correcta>=0&&q.correcta<4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampa&&q.referencia);
 assert.ok(q.referencia.includes('https://'),'Referencia sin fuente '+q.id);
 assert.ok(cotejo.includes('### '+q.id+' — '+q.pregunta),'Sin cotejo por pregunta '+q.id);
}
const extA=additional?.preguntas.filter(q=>q.tema===18);
const extB=economy.preguntas.filter(q=>q.tema===18);
assert.equal(extA?.length,4);assert.equal(extB.length,4);
const all=[...extA,...extB];
const articleA=['108.4','108.2.a','182.1','109.2'];
const articleB=['56.3','10.1','108.4','182.1'];
for(const [i,q] of all.entries()){
 assert.ok(q.id&&!ids.has(q.id),'Duplicado extra '+q.id);ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones).size,4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampaExamen&&q.referencia);
 const article=i<4?articleA[i]:articleB[i-4];
 const major=article.split('.')[0];
 assert.ok(q.referencia.includes('art. '+article),'Sin referencia artículo '+q.id);
 assert.ok(q.referencia.includes('BOE-A-2026-3217#a'+major),'Ancla oficial incorrecta '+q.id);
}
const close=matrix.cierreDocumentalT18_20261106;
assert.equal(close?.resultado,'CIERRE_DOCUMENTAL_REGISTRADO_CON_RESERVAS');
assert.equal(close?.bloquesMatriz,8);
assert.equal(close?.bancoOriginal,12);
assert.equal(close?.alternativasOriginales,48);
assert.equal(close?.bancoComplementarioLote,4);
assert.equal(close?.bancoComplementarioEconomia,4);
assert.equal(close?.alternativasComplementarias,32);
assert.equal(close?.ejerciciosDocumentales,20);
assert.equal(close?.alternativasDocumentales,80);
assert.equal(close?.aprobacionUsuario,false);
assert.equal(close?.certificacionIntegral,false);
assert.equal(close?.ciPendiente,true);
assert.equal(close?.navegadorE2E,false);
assert.ok(guide.includes('CIERRE_DOCUMENTAL_T18_20261106.md'));
assert.ok(status.includes('CIERRE_DOCUMENTAL_T18_20261106.md'));
assert.equal(ids.size,20);
console.log('UC3M T18: 8 BLOQUES, 20 PREGUNTAS Y 80 ALTERNATIVAS, REFERENCIAS EXACTAS, CIERRE DOCUMENTAL CON RESERVAS');
